import {lessons} from './lessons.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='koto-arrays-v2';
function readSaved(key){
  try {
    const value=JSON.parse(localStorage.getItem(key)||'null');
    return value&&typeof value==='object'&&!Array.isArray(value)?value:null;
  } catch {return null}
}
// New tasks have new requirements. Keep old work in v1, but don't credit it
// towards the new practice. Answers to the unchanged quizzes carry over.
const saved=readSaved(storageKey)||{quiz:readSaved('koto-arrays-v1')?.quiz||{}};
let state={quiz:{},passed:{},drafts:{},...saved};
if(!state.quiz||typeof state.quiz!=='object')state.quiz={};
if(!state.passed||typeof state.passed!=='object')state.passed={};
if(!state.drafts||typeof state.drafts!=='object')state.drafts={};
let lesson=lessons[0],tab='theory',taskIndex=0,algorithmStep=0,quizPick=null,demoArray=[],demoIndex=2,demoTimer=null,lastResults=null,worker=null,runTimer=null,toastTimer=null;
let solutionVisible=false,hintVisible=false;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{$('.save-status').textContent='Сохранение недоступно'}updateProgress()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function mascot(small=false){return `<svg viewBox="0 0 250 260" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Кото — рыжий кот с фиолетовым шарфом"><defs><linearGradient id="fur${small?'s':''}" x1="0" y1="0" x2=".9" y2="1"><stop stop-color="#ffda9e"/><stop offset="1" stop-color="#f5b572"/></linearGradient></defs><ellipse cx="126" cy="241" rx="65" ry="9" fill="#d4baa3" opacity=".25"/><path d="M177 202c42 7 52-17 35-34-9-8-18-3-14 6 9 17-16 17-24 12" fill="#e9aa68" stroke="#775242" stroke-width="3.2" stroke-linejoin="round"/><path d="M86 133c-10 22-20 61-15 89 3 17 24 17 34 11 12 6 35 6 48 0 13 7 31 4 32-10 2-30-10-68-22-88" fill="url(#fur${small?'s':''})" stroke="#775242" stroke-width="3.2"/><path d="M98 164c9-12 40-17 54-1 12 15 14 44 7 53-16 14-44 16-60 1-9-10-9-39-1-53" fill="#ffe8c2"/><path d="M85 204c-2 10-2 18 0 22m17-5v11m51-11v11m18-28c3 8 3 15 0 21" fill="none" stroke="#ba8459" stroke-width="2.3" stroke-linecap="round"/><path d="m64 82 0-57c0-6 5-7 10-3l36 30h30l35-29c5-5 10-3 10 3l0 58" fill="url(#fur${small?'s':''})" stroke="#775242" stroke-width="3.2" stroke-linejoin="round"/><path d="m73 34 4 36 22-13zm102 1-24 22 22 13z" fill="#e6a498"/><path d="M65 70c-12 17-14 45-3 61 12 18 37 26 64 26 28 0 51-8 62-26 12-19 7-47-4-61-17-23-96-24-119 0" fill="url(#fur${small?'s':''})" stroke="#775242" stroke-width="3.2"/><path d="m116 52 4 16m14-16-3 17m-28-14 7 12" stroke="#d99558" stroke-width="5" stroke-linecap="round"/><ellipse cx="83" cy="113" rx="13" ry="7" fill="#eeaf94" opacity=".8"/><ellipse cx="166" cy="113" rx="13" ry="7" fill="#eeaf94" opacity=".8"/><path d="M82 94c5-5 11-5 16 0m52 0c5-5 11-5 16 0" fill="none" stroke="#624538" stroke-width="4" stroke-linecap="round"/><path d="m120 109 6 5 6-5z" fill="#9a6a5c"/><path d="M126 114v5m0-1c-1 8-12 8-15 1m15-1c1 8 12 8 15 1" fill="none" stroke="#775242" stroke-width="2.2" stroke-linecap="round"/><path d="m66 112-18-4m19 12-19 1m136-9 18-4m-19 12 19 1" stroke="#99705a" stroke-width="2" stroke-linecap="round"/><path d="M77 143c18 10 76 11 94-2l1 14c-20 16-69 17-95 1z" fill="#8d6db9" stroke="#74528f" stroke-width="2.4"/><path d="m151 156 20-3 10 42-15-4-10 10z" fill="#9c7ac7" stroke="#74528f" stroke-width="2.4" stroke-linejoin="round"/><path d="M77 173c-12 2-21 16-14 23 7 6 21-3 26-13m77-9c11 2 17 15 11 21-6 6-18-2-23-12" fill="#f7bf7f" stroke="#775242" stroke-width="3" stroke-linecap="round"/><rect x="89" y="168" width="69" height="42" rx="6" fill="#eee5f5" stroke="#a48aba" stroke-width="2.5" transform="rotate(-6 124 190)"/><text x="102" y="194" fill="#8a67b2" font-family="monospace" font-size="17" font-weight="bold" transform="rotate(-6 124 190)">[ ]</text></svg>`}
$('#hero-mascot').innerHTML=mascot();$('#help-mascot').innerHTML=mascot(true);
function updateProgress(){let count=0;for(const l of lessons){if(state.quiz[l.id])count++;for(const t of l.tasks)if(state.passed[t.id])count++}const total=lessons.reduce((n,l)=>n+1+l.tasks.length,0);const percent=Math.round(count/total*100);$('#progress-percent').textContent=percent+'%';$('#progress-bar').style.width=percent+'%';$('#progress-label').textContent=`${count} из ${total} шагов закреплено`;$('#lesson-nav').innerHTML=lessons.map((l,i)=>{const done=state.quiz[l.id]&&l.tasks.every(t=>state.passed[t.id]);return `<button class="lesson-nav-item ${lesson.id===l.id?'active':''}" data-lesson="${l.id}" ${lesson.id===l.id?'aria-current="step"':''}><span class="nav-number">${done?'✓':'0'+(i+1)}</span><span class="nav-copy">${esc(l.title)}<small>§${l.id}</small></span>${done?'<span class="nav-done">✓</span>':''}</button>`}).join('')}
function codeMarkup(code){const regex=/(\{[\s\S]*?\}|\/\/[^\n]*|'(?:''|[^'])*'|\b(?:program|var|const|array|of|integer|real|boolean|string|begin|end|for|to|downto|do|if|then|else|while|repeat|until|and|or|not|div|mod|true|false)\b|\b\d+(?:\.\d+)?\b)/gi;return code.split('\n').map((line,i)=>`<span class="code-line ${isActiveLine(i+1,code)?"current":""} "><span class="ln">${i+1}</span>${line.split(regex).map(t=>{if(/^\{|^\/\//.test(t))return `<span class="comment">${esc(t)}</span>`;if(/^'/.test(t))return `<span class="str">${esc(t)}</span>`;if(/^\d/.test(t))return `<span class="num">${esc(t)}</span>`;if(/^(program|var|const|array|of|integer|real|boolean|string|begin|end|for|to|downto|do|if|then|else|while|repeat|until|and|or|not|div|mod|true|false)$/i.test(t))return `<span class="kw">${esc(t)}</span>`;return esc(t)}).join('')}</span>`).join('')}
function codePanel(code,id='example-code',title='example.pas'){
  return `<div class="code-panel"><div class="code-toolbar"><span><span class="window-dots"><i></i><i></i><i></i></span>${title}</span></div><pre class="code-list" id="${id}">${codeMarkup(code)}</pre><div class="code-tip">:= присвоить · [i] обратиться к ячейке · ; закончить команду</div></div>`;
}
function note(){return `<aside class="mascot-note"><div class="mini-mascot">${mascot(true)}</div><div><h3>Кото на заметку</h3><p>${esc(lesson.mascot)}</p><button class="text-button" data-open-help>Объясни ещё проще ↗</button></div></aside>`}
function extraMarkup(){return `<section class="extra-section"><h3>Ещё немного из §${lesson.id} <span style="font-size:10px;color:#b0a3ba;font-weight:400">· открой, когда захочется глубже</span></h3>${lesson.extra.map(x=>`<details><summary>${esc(x.title)}</summary><p>${esc(x.text)}</p>${x.code?`<pre>${esc(x.code)}</pre>`:''}</details>`).join('')}</section>`}
function go(nextLesson=lesson.id,nextTab='theory',nextTask=0){const hash=`#lesson-${nextLesson}/${nextTab}/${nextTask}`;if(location.hash===hash)readRoute();else location.hash=hash}
function stopRun(){if(worker){worker.terminate();worker=null}clearTimeout(runTimer)}
function readRoute(){stopRun();clearInterval(demoTimer);demoTimer=null;const match=location.hash.match(/^#lesson-([3-6])(?:\/(theory|algorithm|practice))?(?:\/(\d+))?$/);lesson=lessons.find(l=>l.id===Number(match?.[1]))||lessons[0];tab=match?.[2]||'theory';taskIndex=Math.min(Number(match?.[3]||0),lesson.tasks.length-1);quizPick=state.quiz[lesson.id]?lesson.quiz.answer:null;algorithmStep=0;demoArray=[...lesson.demo.array];demoIndex=lesson.id===3?2:-1;hintVisible=false;solutionVisible=false;lastResults=null;render();$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false')}
function render(){updateProgress();$('#lesson-kicker').textContent=`УРОК 0${lesson.id-2} / 04 · §${lesson.id}`;$('#lesson-title').textContent=lesson.title;$('#lesson-subtitle').textContent=lesson.subtitle;document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});$('#lesson-content').setAttribute('aria-labelledby','tab-'+tab);if(tab==='theory')renderTheory();if(tab==='algorithm')renderAlgorithm();if(tab==='practice')renderPractice()}
function renderTheory(){const found=state.quiz[lesson.id];$('#lesson-content').innerHTML=`<div class="content-grid"><section class="panel"><div class="intro-heading"><span class="square-icon">${['▦','∑','⌕','↗'][lesson.id-3]}</span><h3>${['Один массив — много значений','Складывай по одному','У каждой находки есть условие','В поисках рекордсмена'][lesson.id-3]}</h3></div><p class="body-text">${esc(lesson.intro)}</p><div class="array-lab"><div class="array-caption"><b>массив a</b><span>нажми на ячейку ↓</span></div><div class="array-cells" id="array-cells"></div><div class="array-note" id="array-note" aria-live="polite"></div><div class="array-controls"><button class="demo-play" id="demo-play">▷ ${lesson.id===3?'Пройти по ячейкам':'Запустить по шагам'}</button><button class="shuffle" id="shuffle">Другие числа ↻</button></div>${lesson.id===6?'<div class="bar-chart" id="bar-chart" aria-label="Гистограмма элементов"></div>':''}</div></section>${note()}</div><div class="concepts concepts-${lesson.concepts.length}">${lesson.concepts.map((c,i)=>`<article class="concept"><span class="concept-number">0${i+1}</span><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p></article>`).join('')}</div>${lesson.id===4?'<div class="pie-demo"><div class="pie" role="img" aria-label="Круговая диаграмма массива 7, 3, 8, 2, 5"></div><p>Пример [7, 3, 8, 2, 5] — части целого.<br>Для первого элемента: 7 / 25 × 360° = 100,8°.</p></div>':''}<section class="quiz-card"><div class="card-label">МИНИ-ПРОВЕРКА · 1 ВОПРОС</div><h3>${esc(lesson.quiz.question)}</h3><div class="quiz-options">${lesson.quiz.options.map((o,i)=>`<button class="quiz-option ${quizPick===i?(i===lesson.quiz.answer?'correct':'wrong'):''}" data-quiz="${i}"><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div><div class="quiz-feedback" id="quiz-feedback" aria-live="polite">${quizPick!==null?esc(lesson.quiz.explanations[quizPick]):''}</div></section><div class="next-row"><span>${found?'✓ Основная идея закреплена':'Можно идти дальше и вернуться к вопросу позже'}</span><button class="primary" data-go="algorithm">Теперь к алгоритму <span>→</span></button></div>${extraMarkup()}`;renderDemo()}
function renderDemo(){const op=lesson.demo.operation;$('#array-cells').innerHTML=demoArray.map((x,i)=>`<button class="array-cell ${i===demoIndex?'selected':''} ${demoIndex>=0&&i<demoIndex?'visited':''}" data-cell="${i}" aria-label="a[${i+1}] равно ${x}" aria-pressed="${i===demoIndex}"><span class="array-index">${i+1}</span><span class="array-value">${x}</span></button>`).join('');let text='';if(demoIndex<0){text={index:'Выбери ячейку — увидишь её адрес и содержимое.',sum:'Начинаем с s := 0. Ни одного числа ещё не добавили.',search:'Ищем чётные числа. Сначала k := 0.',max:'Первый кандидат — a[1] = '+demoArray[0]+'. Сравним его с остальными.'}[op]}else{const prefix=demoArray.slice(0,demoIndex+1);if(op==='index')text=`a[${demoIndex+1}] = ${demoArray[demoIndex]}. ${demoIndex+1} — индекс, ${demoArray[demoIndex]} — значение.`;if(op==='sum')text=`s = ${prefix.join(' + ')} = ${prefix.reduce((a,b)=>a+b,0)}${demoIndex===demoArray.length-1?' · готово!':''}`;if(op==='search'){const count=prefix.filter(x=>x%2===0).length;text=`${demoArray[demoIndex]} mod 2 ${demoArray[demoIndex]%2===0?'= 0 → подходит':'≠ 0 → пропускаем'}. Найдено чётных: ${count}.`}if(op==='max')text=`После ${demoIndex+1} ${demoIndex===0?'ячейки':'ячеек'}: mx = ${Math.max(...prefix)}${demoIndex===demoArray.length-1?' · это максимум массива!':''}.`}$('#array-note').textContent=text;if(lesson.id===6){const max=Math.max(...demoArray);$('#bar-chart').innerHTML=demoArray.map(x=>`<div style="height:${Math.round(x/max*80)}px" class="${x===max?'highest':''}"><span>${x}</span></div>`).join('')}}
function renderAlgorithm(){$('#lesson-content').innerHTML=`<div class="card-label">ОТ ИДЕИ К КОДУ</div><h3 style="font-size:20px;letter-spacing:-.5px;margin-bottom:22px">${esc(lesson.algorithmTitle)}</h3><div class="algorithm-layout"><div class="steps-list">${lesson.steps.map((s,i)=>`<button class="algorithm-step ${i===algorithmStep?'active':''}" data-step="${i}" aria-pressed="${i===algorithmStep}"><span>${i+1}</span><div><b>${esc(s.title)}</b><p>${esc(s.text)}</p></div></button>`).join('')}</div>${codePanel(lesson.code)}</div><div class="hint-box" id="step-explanation">Шаг ${algorithmStep+1}: ${esc(lesson.steps[algorithmStep].text)}</div><div class="next-row algorithm-bottom"><button class="secondary" id="step-next">Следующий шаг ↻</button><button class="primary" data-go="practice">Попробовать самому <span>→</span></button></div>${extraMarkup()}`}
function isActiveLine(line,code){if(tab!=='algorithm'||code!==lesson.code)return false;const lines={3:[[2,3,4],[6],[7,8],[9,10]],4:[[6,7,8],[9],[10,11],[12]],5:[[6,7,8],[9],[10,11],[12],[13]],6:[[6,7,8],[9],[10,11,12],[13]]};return lines[lesson.id][algorithmStep]?.includes(line)}
function currentTask(){return lesson.tasks[taskIndex]}
function renderPractice(){hintVisible=false;solutionVisible=false;
  const task=currentTask();
  $('#lesson-content').innerHTML=`
    <div class="practice-picker" role="group" aria-label="Задачи урока">
      ${lesson.tasks.map((t,i)=>`<button class="task-choice ${i===taskIndex?'active':''}" data-task="${i}">${i+1}. ${esc(t.title)}${state.passed[t.id]?'<span class="task-check">✓</span>':''}</button>`).join('')}
    </div>
    <section class="task-intro">
      <div>
        <div class="card-label">САМОСТОЯТЕЛЬНО · ${taskIndex+1} / ${lesson.tasks.length}</div>
        <h3>${esc(task.title)}</h3>
        <p>${esc(task.description)}</p>
        <div class="transfer-note"><b>Что меняется после примера</b>${esc(task.transferNote)}</div>
        <div class="format-row"><b>Ввод:</b> ${esc(task.inputFormat)}</div>
        <div class="format-row"><b>Вывод:</b> ${esc(task.outputFormat)}</div>
      </div>
      <div class="sample-io"><div><span>Пример ввода</span><pre>${esc(task.tests[0].input)}</pre></div><div><span>Вывод</span><pre>${esc(task.tests[0].expected)}</pre></div></div>
    </section>
    <div class="editor-wrap">
      <div class="editor-toolbar"><span><span class="window-dots"><i></i><i></i><i></i></span>solution.pas</span><div><button id="download-code">↓ Скачать .pas</button><button id="reset-code">↻ Очистить</button></div></div>
      <div class="editor-area"><pre class="editor-lines" id="editor-lines" aria-hidden="true"></pre><textarea class="code-editor" id="code-editor" aria-label="Редактор решения на Pascal" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" wrap="off"></textarea></div>
      <div class="editor-footer"><span>Pascal · ${task.tests.length} тестов · Ctrl + Enter</span><button class="run-button" id="run-code"><span class="play">▷</span> Проверить решение</button></div>
    </div>
    <div class="practice-actions"><button id="hint-button">✦ Подсказка Кото</button><button id="solution-button" ${state.passed[task.id]?'':'hidden'}>Сравнить с разбором</button><button id="syntax-button">Памятка по синтаксису</button></div>
    <p class="practice-note">Напиши программу с нуля. Твой черновик сохраняется. Разбор готового решения откроется после прохождения всех тестов.</p>
    <div id="practice-assist"></div>
    <div id="test-results" aria-live="polite"></div>
    <div id="solution-area"></div>
    <div class="next-row"><button class="secondary" data-go="algorithm">← К алгоритму</button><button class="primary" id="next-practice">${taskIndex<lesson.tasks.length-1?'Следующая задача':(lesson.id===6?'Завершить маршрут':'Следующий урок')} <span>→</span></button></div>
    ${state.passed[task.id]?'<div class="completed-banner">✓ Ты уже прошёл все тесты этой задачи. Можешь поэкспериментировать с другим решением — достижение сохранено.</div>':''}`;
  const editor=$('#code-editor');
  editor.value=typeof state.drafts[task.id]==='string'?state.drafts[task.id]:'';
  updateLines();
  editor.addEventListener('input',()=>{
    state.drafts[task.id]=editor.value;
    save();
    updateLines();
  });
  editor.addEventListener('scroll',()=>{$('#editor-lines').scrollTop=editor.scrollTop});
  editor.addEventListener('keydown',e=>{
    if(e.key==='Tab'){
      e.preventDefault();
      editor.setRangeText('  ',editor.selectionStart,editor.selectionEnd,'end');
      editor.dispatchEvent(new Event('input'));
    }
    if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){
      e.preventDefault();
      runCode();
    }
  });
}
function updateLines(){const editor=$('#code-editor');if(editor)$('#editor-lines').textContent=Array.from({length:editor.value.split('\n').length},(_,i)=>i+1).join('\n')}
function runCode(){if(worker)return;const source=$('#code-editor').value;
if(!source.trim()){
  $('#test-results').innerHTML='<div class="hint-box">Редактор пока пуст. Напиши свою программу на Pascal и затем запусти проверку. Синтаксис можно вспомнить в памятке.</div>';
  return;
}
state.drafts[currentTask().id]=source;save();$('#run-code').disabled=true;$('#run-code').textContent='Проверяю…';$('#test-results').innerHTML='<p class="empty-msg">Запускаю программу на разных наборах данных…</p>';const task=currentTask();const end=()=>{stopRun();const b=$('#run-code');if(b){b.disabled=false;b.innerHTML='<span class="play">▷</span> Проверить решение'}};try{worker=new Worker(new URL('./runner.js',import.meta.url),{type:'module'});worker.onmessage=e=>{const results=e.data.results;end();lastResults=results;showResults(results);if(results.every(r=>r.passed)){state.passed[task.id]=true;save();$('#solution-button').hidden=false;toast('Получилось! Все тесты пройдены ✦');document.querySelectorAll(`[data-task="${taskIndex}"]`).forEach(b=>{if(!b.querySelector('.task-check'))b.insertAdjacentHTML('beforeend','<span class="task-check">✓</span>')})}};worker.onerror=()=>{end();$('#test-results').innerHTML='<div class="hint-box">Не удалось запустить проверку. Открой сайт через HTTP (GitHub Pages или локальный сервер), затем обнови страницу.</div>'};runTimer=setTimeout(()=>{end();lastResults=[{passed:false,error:'Программа работала слишком долго. Проверь условия циклов и изменение счётчика.'}];showResults(lastResults)},3500);worker.postMessage({source,tests:task.tests})}catch(e){end();$('#test-results').innerHTML=`<div class="hint-box">${esc(e.message)}</div>`}}
function feedbackFor(results){const first=results.find(r=>!r.passed);if(!first)return 'На всех проверочных данных ответ совпал. Объясни себе, почему алгоритм работает, и переходи дальше.';if(first.error){if(/границ|диапазон|индекс/i.test(first.error))return 'Обращение вышло за границы массива. Проверь индексы и границы цикла: обычно нужны 1..n.';if(/лимит|долго|шаг/i.test(first.error))return 'Похоже, цикл не заканчивается. Проверь его условие и изменение переменных.';if(/ввод|значен|данных/i.test(first.error))return 'Проверь порядок read: сначала длина, затем элементы и дополнительные значения по условию задачи.';return 'Программа остановилась с ошибкой. Номер строки поможет найти команду; полное сообщение — ниже.'}if(first.actual.trim()==='')return 'Ответ пустой. Проверь, есть ли write или writeln и выполняется ли эта команда.';if(lesson.id===6&&/Отрицатель|отрицатель/.test(first.label))return 'Начинай поиск минимума и максимума с a[1], а не с нуля. Для количества минимумов сначала найди само минимальное значение.';if(lesson.id===5&&taskIndex===1)return 'Нужен последний индекс: обновляй результат при каждом совпадении. Если число не найдено, ответ должен остаться равным 0.';return 'Программа запускается, но ответ пока отличается. Открой неудачный тест и сравни ожидаемый вывод со своим. '+currentTask().hint}
function showResults(results){const passed=results.filter(r=>r.passed).length,all=passed===results.length;$('#test-results').innerHTML=`<section class="result-box"><div class="result-summary ${all?'success':''}"><span class="result-icon">${all?'✓':'↻'}</span><div><h3>${all?'Отлично, всё получилось!':`Пройдено ${passed} из ${results.length} тестов`}</h3><p>${esc(feedbackFor(results))}</p></div></div>${results.map((r,i)=>`<details class="test-row" ${!r.passed?'open':''}><summary><span class="test-icon ${r.passed?'pass':''}">${r.passed?'✓':'○'}</span>Тест ${i+1} · ${esc(r.label||'Выполнение программы')} <span style="color:#a596ae;font-size:9px">${r.passed?'верно':'проверь'}</span></summary>${r.error?`<p class="runtime-error">${esc(r.error)}</p>`:''}${r.input!==undefined?`<div class="test-detail"><div><label>Входные данные</label><pre>${esc(r.input)}</pre></div><div><label>Ожидаемый ответ</label><pre>${esc(r.expected)}</pre></div><div><label>Твой ответ</label><pre>${esc(r.actual)||'(пусто)'}</pre></div></div>`:''}</details>`).join('')}</section>`}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function openHelp(){if(!$('#help-dialog').open)$('#help-dialog').showModal();$('#help-answer').textContent=`Сейчас мы разбираем §${lesson.id}: «${lesson.title}». Выбери, с чем помочь.`}
function showHelp(kind){const answers={simpler:lesson.intro+'\n\nПопробуй нажать на ячейки в блоке «Понять»: адрес и значение станут видны отдельно.',pitfall:lesson.mascot,code:lesson.steps.map((s,i)=>`${i+1}. ${s.title}. ${s.text}`).join('\n\n'),error:lastResults?feedbackFor(lastResults):'Сначала открой «Попрактиковаться», напиши свою программу и нажми «Проверить решение». Я покажу результат каждого теста. Если возникнет ошибка, здесь появится подсказка.'};$('#help-answer').textContent=answers[kind]}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lesson){go(Number(b.dataset.lesson));return}if(b.dataset.tab){go(lesson.id,b.dataset.tab);return}if(b.dataset.go){go(lesson.id,b.dataset.go);return}if(b.dataset.task!==undefined){go(lesson.id,'practice',Number(b.dataset.task));return}if(b.dataset.cell!==undefined){clearInterval(demoTimer);demoTimer=null;$('#demo-play').textContent='▷ Запустить по шагам';demoIndex=Number(b.dataset.cell);renderDemo();return}if(b.dataset.quiz!==undefined){clearInterval(demoTimer);demoTimer=null;quizPick=Number(b.dataset.quiz);if(quizPick===lesson.quiz.answer){state.quiz[lesson.id]=true;save()}renderTheory();return}if(b.dataset.step!==undefined){algorithmStep=Number(b.dataset.step);renderAlgorithm();return}if(b.dataset.close){$('#'+b.dataset.close).close();return}if(b.hasAttribute('data-open-help')){openHelp();return}if(b.dataset.help){showHelp(b.dataset.help);return}switch(b.id){case'menu-button':{const open=$('#sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String(open));break}case'help-button':openHelp();break;case'source-button':$('#source-dialog').showModal();break;case'shuffle':clearInterval(demoTimer);demoTimer=null;demoArray=Array.from({length:5},()=>Math.floor(Math.random()*15)+1);demoIndex=lesson.id===3?2:-1;$('#demo-play').textContent='▷ Запустить по шагам';renderDemo();break;case'demo-play':if(demoTimer){clearInterval(demoTimer);demoTimer=null;b.textContent='▷ Продолжить';break}demoIndex=-1;renderDemo();b.textContent='Ⅱ Пауза';demoTimer=setInterval(()=>{demoIndex++;renderDemo();if(demoIndex>=demoArray.length-1){clearInterval(demoTimer);demoTimer=null;b.textContent='↻ Ещё раз'}},1000);break;case'step-next':algorithmStep=(algorithmStep+1)%lesson.steps.length;renderAlgorithm();break;case'run-code':runCode();break;case'reset-code':stopRun();state.drafts[currentTask().id]='';save();lastResults=null;renderPractice();toast('Редактор очищен');break;case'download-code':download(`koto-${currentTask().id}.pas`,$('#code-editor').value);break;case'hint-button':hintVisible=!hintVisible;$('#practice-assist').innerHTML=hintVisible?`<div class="hint-box">✦ ${esc(currentTask().hint)}</div>`:'';break;case'syntax-button':$('#practice-assist').innerHTML='<div class="hint-box"><b>Памятка:</b> := присвоить, = сравнить; a[i] — элемент; read(a[i]) — ввод; writeln(x) — вывод. После then перед else точку с запятой не ставим. Несколько команд внутри цикла или условия объединяем begin … end. Массивы объявляем до основного begin. Ввод в тренажёре — поток значений: пробелы и переносы равнозначны.</div>';break;case'solution-button':if(!state.passed[currentTask().id])return;solutionVisible=!solutionVisible;$('#solution-area').innerHTML=solutionVisible?`<div class="solution-box"><p class="solution-label">Твоя программа уже прошла все тесты. Сравни её с одним из правильных вариантов и объясни различия в командах.</p>${codePanel(currentTask().solution,'solution-code','solution-explained.pas')}<p class="solution-label" style="margin-top:12px">${esc(currentTask().hint)}</p></div>`:'';break;case'next-practice':if(taskIndex<lesson.tasks.length-1)go(lesson.id,'practice',taskIndex+1);else if(lesson.id<6)go(lesson.id+1,'theory');else{const missing=lessons.find(l=>!state.quiz[l.id]||l.tasks.some(t=>!state.passed[t.id]));if(missing){go(missing.id,state.quiz[missing.id]?'practice':'theory',Math.max(0,missing.tasks.findIndex(t=>!state.passed[t.id])));toast('Вернёмся к уроку, где ещё есть незакреплённые шаги')}else toast('Весь маршрут пройден. Ты отлично поработал! ✦')}break;case'export-progress':download('koto-progress.json',JSON.stringify({course:'Массивы §3–6',exportedAt:new Date().toISOString(),quiz:state.quiz,passed:state.passed,drafts:state.drafts},null,2),'application/json');toast('Прогресс скачан');break}});
document.querySelector('.lesson-tabs').addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const tabs=['theory','algorithm','practice'];let index=tabs.indexOf(tab);index=e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowRight'?1:2))%3;go(lesson.id,tabs[index]);setTimeout(()=>$('#tab-'+tabs[index]).focus(),0)});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const rect=d.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)d.close()}}));
window.addEventListener('hashchange',readRoute);window.addEventListener('beforeunload',stopRun);readRoute();
